(92, 'INDULGE', '饮食', '今天慢慢吃，吃到觉得够了就停', 0, FALSE, TRUE, 'GIVE', '慢是放纵和暴食的分界线', '慢慢吃，够了就停\n把注意力放回吃本身。注意 2026 年更新的元分析发现"当餐吃更多"证据不足，只有"下一餐"显著', 'B', 'science-updates'),
(93, 'INDULGE', '饮食', '今天给自己买一杯比平时贵一点的饮料', 0, FALSE, TRUE, 'GIVE', '日常里"贵一点"，是最低成本的善待', '一杯比平时贵一点的饮料\n日常里的一次"贵一点"，是成本最低的善待', 'B', NULL),
(94, 'INDULGE', '社交', '今天对一个人说一句你一直想说、但没说出口的话', 0, FALSE, TRUE, 'GIVE', '把"以后再说"变成今天', '说一句一直没说出口的话\n把"以后再说"变成今天，避免它变成永远不说', 'B', NULL),
(95, 'INDULGE', '注意力', '今天允许自己发呆 10 分钟，什么都不想', 0, FALSE, TRUE, 'STOP', '空白是恢复，不是浪费', '发呆 10 分钟，什么都不想\n放空时大脑并不停机；空白是恢复的一种', 'B', NULL),
(96, 'INDULGE', '观察', '今天去一个你一直想去、但觉得"没必要"的地方', 0, FALSE, TRUE, 'GIVE', '"没必要"正是它该被做的理由', '去那个"没必要"的地方\n用"必要性"当门槛，很多事就永远排在后面', 'B', NULL),
(97, 'INDULGE', '睡眠', '今天可以赖床，不回任何消息', 0, FALSE, TRUE, 'STOP', '一次不响应，世界不会出事', '不回消息，先躺着\n响应速度是可以自己定的；一次不响应不会出事', 'B', NULL),
(98, 'INDULGE', '情绪', '今天留一个下午，只做你喜欢的事', 0, FALSE, TRUE, 'GIVE', '给"喜欢"留出时间块，而不是缝隙', '留一个下午只做喜欢的事\n喜欢的事需要整块时间，否则永远只能待在缝隙里', 'B', NULL),
(99, 'INDULGE', '情绪', '今天可以把一件事做到一半就放下', 0, FALSE, TRUE, 'STOP', '完成欲不是义务', '允许自己做到一半就放下\n不是所有事都值得做完。但"未完成"本身也会占着注意力（Leroy 2009），所以这条适合用在你本来就不想做的事上', 'B', NULL),
(100, 'INDULGE', '运动', '今天去玩一次（打球、游泳、骑车都行），不算锻炼', 0, FALSE, TRUE, 'GIVE', '把运动从"任务"里赎回来', '玩一次（不算锻炼），之后情绪通常会好一点\n单次有氧运动后积极情绪上升，量级小到中等\nReed & Ones (2006), Psychology of Sport and Exercise, 7(5), 477–514（元分析）', 'A', 'meta-analysis');
